import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"Assembly and Structured Presentation","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/assembly.md","filePath":"en/modules/corelib/assembly.md","lastUpdated":null}'),d={name:"en/modules/corelib/assembly.md"};function n(s,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="assembly-and-structured-presentation" tabindex="-1">Assembly and Structured Presentation <a class="header-anchor" href="#assembly-and-structured-presentation" aria-label="Permalink to &quot;Assembly and Structured Presentation&quot;">​</a></h1><p>Assembly rebuilds final item display from structured module layers. This prevents modules from overwriting each other&#39;s lore.</p><h2 id="common-layers" tabindex="-1">Common layers <a class="header-anchor" href="#common-layers" aria-label="Permalink to &quot;Common layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Namespace</th><th>Order</th><th>Meaning</th></tr></thead><tbody><tr><td><code>forge</code></td><td><code>100</code></td><td>Forge layer.</td></tr><tr><td><code>strengthen</code></td><td><code>200</code></td><td>Strengthening layer.</td></tr><tr><td><code>gem</code></td><td><code>300</code></td><td>Gem layer.</td></tr><tr><td><code>cooking</code></td><td><code>10000</code></td><td>Cooking display layer.</td></tr></tbody></table><p>Lower order appears earlier. CoreLib reads all registered layers and renders the final name and lore.</p><p>Namespace IDs are normalised on registration: trimmed, lowercased, spaces replaced with underscores, and a blank ID becomes <code>unknown</code>.</p><h2 id="name-contributions" tabindex="-1">Name contributions <a class="header-anchor" href="#name-contributions" aria-label="Permalink to &quot;Name contributions&quot;">​</a></h2><p>Layers may also decorate the item name. The position enum values are <code>PREFIX</code> and <code>POSTFIX</code> (there is no <code>SUFFIX</code>); an unknown or blank value falls back to <code>POSTFIX</code>.</p><h2 id="lore-operation-ledger" tabindex="-1">Lore operation ledger <a class="header-anchor" href="#lore-operation-ledger" aria-label="Permalink to &quot;Lore operation ledger&quot;">​</a></h2><p>Each <code>name_actions</code> / <code>lore_actions</code> execution is recorded under the item PDC key <code>emaki:item.operations</code> with an <code>operationId</code> and a <code>sourceNamespace</code>, so a single module&#39;s changes can be reverted precisely:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>apply(itemStack, operationId, sourceNamespace, nameActions, loreActions, variables)</code></td><td>Execute the operations and record them into PDC.</td></tr><tr><td><code>revert(itemStack, operationId)</code></td><td>Revert one specific operation.</td></tr><tr><td><code>revertAll(itemStack, sourceNamespace)</code></td><td>Revert every operation from one namespace.</td></tr></tbody></table><h2 id="insert-anchor-behaviour" tabindex="-1">Insert anchor behaviour <a class="header-anchor" href="#insert-anchor-behaviour" aria-label="Permalink to &quot;Insert anchor behaviour&quot;">​</a></h2><p>An empty <code>anchor</code> and an <code>anchor</code> that matches nothing do not behave the same way:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Empty <code>anchor</code></th><th><code>anchor</code> matches nothing</th></tr></thead><tbody><tr><td><code>insert_below</code></td><td>Insert at the end of the lore.</td><td>Insert at the end of the lore.</td></tr><tr><td><code>insert_above</code></td><td>Insert at the start of the lore.</td><td>Insert at the end of the lore.</td></tr></tbody></table><p>Anchors use <strong>contains</strong> matching and stop at the first matching line.</p><h2 id="advice" tabindex="-1">Advice <a class="header-anchor" href="#advice" aria-label="Permalink to &quot;Advice&quot;">​</a></h2><p>Store real state in PDC or payloads. Use lore only as presentation. When a module changes item state, request a proper refresh.</p>',17)])])}const u=t(d,[["render",n]]);export{p as __pageData,u as default};
